def can(start):
    seen, todo = {start}, [start]
    while todo:
        s = todo.pop()
        if sorted(s)[:2] == [0, 0]: return True
        for i in range(3):
            for j in range(i):
                if s[i] and s[j]:
                    t = list(s); t[i] -= 1; t[j] -= 1; t[3 - i - j] += 2; t = tuple(t)
                    if t not in seen: seen.add(t); todo.append(t)
    return False
result = [k + 1 for k, s in enumerate([(1, 2, 3), (2, 5, 8), (1, 1, 1), (4, 4, 7)]) if can(s)]
